import { afterEach, describe, expect, it, vi } from 'vitest'
import fixture from '../fixtures/furniture-kpis.json'

// Generated by running Furniture-Collect's own readKpis (src/server/commandCenter.ts)
// over three items, so the contract is checked against the real output shape.
describe('furniture KPI contract', () => {
  it('parses what the field app actually returns', async () => {
    const { kpiContract } = await import('@/lib/integrations/furniture/field')
    const k = kpiContract.parse(fixture)
    expect(k.kpis.documented.kg).toBe(50)
    expect(k.headline.basis).toBe('confirmed')
  })

  it('rejects a shape that drifted', async () => {
    const { kpiContract } = await import('@/lib/integrations/furniture/field')
    expect(kpiContract.safeParse({ ...fixture, kpis: { ...fixture.kpis, documented: { kg: '50' } } }).success).toBe(false)
  })
})

describe('field actions', () => {
  afterEach(() => {
    vi.unstubAllEnvs()
    vi.unstubAllGlobals()
    vi.resetModules()
  })

  it('reports not configured without sending anything', async () => {
    vi.stubEnv('FURNITURE_APP_URL', '')
    vi.stubEnv('FURNITURE_COMMAND_CENTER_KEY', '')
    const fetch = vi.fn()
    vi.stubGlobal('fetch', fetch)
    const { runFieldAction } = await import('@/lib/integrations/furniture/field')
    const r = await runFieldAction({ action: 'reopen_apartment', apartmentId: 'x' }, { email: 'a@b.c' })
    expect(r).toMatchObject({ ok: false, error: 'not_configured' })
    expect(fetch).not.toHaveBeenCalled()
  })

  it('sends the actor with the key, once, and passes a refusal through as an answer', async () => {
    vi.stubEnv('FURNITURE_APP_URL', 'https://field.example')
    vi.stubEnv('FURNITURE_COMMAND_CENTER_KEY', 'k'.repeat(40))
    const fetch = vi.fn(async () => new Response(JSON.stringify({ ok: false, error: 'needs_confirmation', state: { outstanding: 2 } }), { status: 409 }))
    vi.stubGlobal('fetch', fetch)
    const { runFieldAction, fieldMessage } = await import('@/lib/integrations/furniture/field')
    const r = await runFieldAction({ action: 'finish_apartment', apartmentId: 'x' }, { email: 'a@b.c', name: 'Yuval' })
    expect(fetch).toHaveBeenCalledTimes(1)
    const [url, init] = fetch.mock.calls[0] as unknown as [string, RequestInit]
    expect(url).toBe('https://field.example/api/command-center')
    expect((init.headers as Record<string, string>).Authorization).toBe(`Bearer ${'k'.repeat(40)}`)
    expect(JSON.parse(String(init.body))).toMatchObject({ action: 'finish_apartment', actor: { email: 'a@b.c', name: 'Yuval' } })
    expect(r).toMatchObject({ ok: false, status: 409, error: 'needs_confirmation' })
    expect(fieldMessage('changed_since_loaded')).toMatch(/Reload/)
  })
})
